
import requests
import base64
import os

# Create a minimal valid JPEG image (1x1 pixel, white)
# minimal jpeg header + data
current_dir = os.path.dirname(os.path.abspath(__file__))
img_path = os.path.join(current_dir, "test_waste.jpg")

# 1x1 white pixel
img_data = base64.b64decode("")

with open("test_waste.jpg", "wb") as f:
    f.write(img_data)

url = "http://127.0.0.1:8000/api/v1/market/analyze-waste/"

print(f"Sending request to {url}...")
try:
    files = {'image': open('test_waste.jpg', 'rb')}
    response = requests.post(url, files=files)
    print(f"Status Code: {response.status_code}")
    print("Response JSON:")
    print(response.json())
except Exception as e:
    print(f"Request failed: {e}")
